#include "parser.h"
#include <string.h>
#include <stdio.h>
static int reg(const char*s){if(!s||s[0]!='R'||s[2])return -1;int n=s[1]-'0';return n>=0&&n<8?n:-1;}
static unsigned op(const char*s){struct P{const char*n;unsigned o;}p[]={{"NOP",0},{"MOV",1},{"LOAD",2},{"STORE",3},{"ADD",16},{"SUB",17},{"MUL",18},{"DIV",19},{"MOD",20},{"AND",21},{"OR",22},{"XOR",23},{"NOT",24},{"SHL",25},{"SHR",26},{"CMP",27},{"JMP",32},{"JE",33},{"JNE",34},{"JG",35},{"JL",36},{"PUSH",48},{"POP",49},{"CALL",50},{"RET",51},{"HALT",255}};for(size_t i=0;i<sizeof(p)/sizeof(p[0]);i++)if(!strcmp(s,p[i].n))return p[i].o;return 0x100;}
int asm_parse_line(const char*line,asm_statement*out,char*err,size_t cap){if(!line||!out)return -1;asm_lexer l;asm_lexer_init(&l,line);asm_token a,b,c;int x=asm_lexer_next(&l,&a);if(x<=0)return 1;if(a.kind!=TOK_IDENT){snprintf(err,cap,"expected opcode");return -1;}unsigned o=op(a.text);if(o>255){snprintf(err,cap,"unknown opcode %s",a.text);return -1;}memset(out,0,sizeof(*out));out->ins.opcode=(uint8_t)o;out->source_pos=a.pos;if(o==0||o==255||o==51)return 0;if((o>=32&&o<=36)||o==50){if(asm_lexer_next(&l,&b)<=0||b.kind!=TOK_NUMBER){snprintf(err,cap,"expected branch address");return -1;}out->ins.imm=b.number;return 0;}if(asm_lexer_next(&l,&b)<=0||b.kind!=TOK_IDENT){snprintf(err,cap,"expected register");return -1;}int rb=reg(b.text);if(rb<0){snprintf(err,cap,"invalid register");return -1;}out->ins.dst=(uint8_t)rb;if(o==24||o==48||o==49)return 0;if(asm_lexer_next(&l,&c)<=0||c.kind!=TOK_COMMA){snprintf(err,cap,"expected comma");return -1;}if(asm_lexer_next(&l,&c)<=0){snprintf(err,cap,"missing operand");return -1;}if(c.kind==TOK_NUMBER){out->ins.imm=c.number;if(o==1)out->ins.flags=1;return 0;}if(c.kind==TOK_IDENT){int rs=reg(c.text);if(rs<0){snprintf(err,cap,"invalid register");return -1;}out->ins.src=(uint8_t)rs;return 0;}snprintf(err,cap,"invalid operand");return -1;}
